def transform(grid):
    h, w = len(grid), len(grid[0])
    size = 5 if h >= 14 else 3
    step = size + 1
    starts = list(range(0, w - size + 1, step))
    layout_top = size + 1
    marker_row = h - 1

    # For each source color, save its glyph and the replacement color.
    glyphs = {}
    replacements = {}
    for s in starts:
        vals = [grid[r][c] for r in range(size) for c in range(s, s + size)
                if grid[r][c] not in (0, 5)]
        if not vals:
            continue
        color = max(set(vals), key=vals.count)
        glyphs[color] = [grid[r][s:s + size] for r in range(size)]
        replacements[color] = grid[marker_row][s + size // 2]

    out = [[0] * (size * size) for _ in range(size * size)]

    # Each lower panel is a placement mask: every colored cell is replaced
    # by that color's top glyph, recolored using its marker.
    for s in starts:
        for r in range(size):
            for c in range(size):
                rr, cc = layout_top + r, s + c
                if rr >= h or cc >= w:
                    continue
                color = grid[rr][cc]
                if color == 0 or color == 5 or color not in glyphs:
                    continue
                glyph = glyphs[color]
                replacement = replacements[color]
                for gr in range(size):
                    for gc in range(size):
                        if glyph[gr][gc] != 0:
                            out[r * size + gr][c * size + gc] = replacement

    return out
